public class GameMain extends Game {
    public GameObject player;
    public int xp, level = 1, kills;
    public double elapsed;
    public boolean over;

    @Override public void onCreate() { build(); }

    @Override public void onUpdate(double delta) {
        if (!over) elapsed += delta;
        if (input.isKeyPressed(Keys.R) && over) build();
    }

    private void build() {
        for (GameObject o : new java.util.ArrayList<>(getObjects())) o.destroy();
        xp = 0; level = 1; kills = 0; elapsed = 0; over = false;
        setWorldBounds(0, 0, 2000, 1400);

        GameObject ground = createObject("Ground");
        ground.addComponent(new TileMap(Assets.GRASS, 32)).generate(63, 44, 7, Assets.GRASS, Assets.GRASS, Assets.GRASS, Assets.GRASS_TUFT);

        player = createObject("Player").setPosition(1000, 700);
        player.addComponent(new Sprite(Assets.PLAYER01, 32, 32));
        Collider2D body = player.addComponent(new CircleCollider2D(12));
        body.layer = Layers.PLAYER;
        player.addComponent(new TopDownCharacterController2D());
        player.addComponent(new Health(100));
        player.addComponent(new PlayerControls());
        player.addComponent(new AutoWeapon());
        player.addComponent(new Spawner());

        GameObject camera = createObject("Camera");
        camera.addComponent(new Camera2D()).follow(player);
    }

    public void gameOver() {
        over = true;
    }

    @Override public void onDrawUI() {
        Health hp = player == null || player.destroyed ? null : player.getComponent(Health.class);
        canvas.drawRect(160, 16, 300, 10, "#3a2030");
        if (hp != null && hp.current > 0) canvas.drawRect(160, 16, 300 * hp.current / hp.max, 10, "#e05050");
        canvas.drawText("LVL " + level + "  XP " + xp + "  Zabici " + kills + "  " + (Math.round(elapsed * 10) / 10.0) + " s", 480, 16, 14, "#aef", "center", "middle");
        if (over) canvas.drawText("KONIEC GRY po " + Math.round(elapsed) + " s — R restartuje", 320, 60, 22, "#ff6060", "center", "middle");
    }
}

