public class Spawner extends Component {
    public double next = 1.0;
    @Override public void onUpdate(double delta) {
        GameMain game = (GameMain) getGame();
        if (game.over) return;
        if (game.elapsed < next) return;
        double interval = Math.max(0.25, 1.2 - game.elapsed / 60);
        next += interval;
        if (countEnemies() >= 150) return;
        double angle = getGame().random.next() * Math.PI * 2;
        double radius = 520;
        double ex = game.player.transform.x + Math.cos(angle) * radius;
        double ey = game.player.transform.y + Math.sin(angle) * radius;
        int pick = (int) (getGame().random.next() * (game.elapsed > 40 ? 3 : game.elapsed > 15 ? 2 : 1));
        Assets sprite = pick == 0 ? Assets.SLIME : pick == 1 ? Assets.BAT : Assets.GHOST;
        double hp = pick == 0 ? 2 : pick == 1 ? 1 : 4;
        double speed = pick == 0 ? 45 : pick == 1 ? 85 : 30;
        spawn(sprite, ex, ey, hp, speed);
    }
    private int countEnemies() {
        int count = 0;
        for (GameObject o : getGame().getObjects()) if (o.hasComponent(Chaser.class)) count++;
        return count;
    }
    private void spawn(Assets sprite, double x, double y, double hp, double speed) {
        GameObject e = getGame().createObject("Enemy").setPosition(x, y);
        e.addComponent(new Sprite(sprite, 28, 28));
        Collider2D body = e.addComponent(new CircleCollider2D(11));
        body.layer = Layers.ENEMY;
        body.mask = Layers.PLAYER | Layers.PROJECTILE;
        e.addComponent(new TopDownCharacterController2D());
        e.addComponent(new Health(hp));
        e.addComponent(new Chaser(speed));
    }
}

