public class Chaser extends Component {
    public double speed, touchCooldown;
    public Chaser(double speed) { this.speed = speed; }
    @Override public void onUpdate(double delta) {
        if (touchCooldown > 0) touchCooldown -= delta;
        GameObject player = ((GameMain) getGame()).player;
        if (player == null || player.destroyed) return;
        requireComponent(TopDownCharacterController2D.class).walk(player.transform.x - transform.x, player.transform.y - transform.y);
    }
    @Override public void onCollision(GameObject other) {
        if (!other.hasComponent(PlayerControls.class) || touchCooldown > 0) return;
        touchCooldown = 0.5;
        Health hp = other.getComponent(Health.class);
        if (hp != null) hp.damage(8);
    }
}

