public class AutoWeapon extends Component {
    public double cooldown = 0.5, timer;
    public double damage = 1, range = 420;
    @Override public void onUpdate(double delta) {
        if (((GameMain) getGame()).over) return;
        timer -= delta;
        if (timer > 0) return;
        GameObject target = nearestEnemy();
        if (target == null) { timer = 0.1; return; }
        timer = cooldown;
        double dx = target.transform.x - transform.x, dy = target.transform.y - transform.y;
        GameObject shot = getGame().createObject("Shot").setPosition(transform.x, transform.y);
        shot.addComponent(new Sprite(Assets.FIREBALL, 14, 14));
        Collider2D area = shot.addComponent(new CircleCollider2D(5).asTrigger());
        area.layer = Layers.PROJECTILE;
        area.mask = Layers.ENEMY;
        shot.addComponent(new Projectile2D(dx, dy, 340, 1.4, gameObject));
        shot.addComponent(new DamageOnHit(damage));
    }
    private GameObject nearestEnemy() {
        GameObject best = null;
        double bestDistance = range * range;
        for (GameObject o : getGame().getObjects()) {
            if (!o.hasComponent(Chaser.class)) continue;
            double dx = o.transform.x - transform.x, dy = o.transform.y - transform.y;
            double d = dx * dx + dy * dy;
            if (d < bestDistance) { bestDistance = d; best = o; }
        }
        return best;
    }
}

