public class DamageOnHit extends Component {
    public double damage;
    public DamageOnHit(double damage) { this.damage = damage; }
    @Override public void onTrigger(GameObject other) {
        Health hp = other.getComponent(Health.class);
        if (hp == null || !other.hasComponent(Chaser.class)) return;
        if (hp.damage(damage)) {
            getGame().audio.playNote("E5", 0.05, "square");
            if (hp.dead) {
                ((GameMain) getGame()).kills++;
                dropGem(other.transform.x, other.transform.y);
            }
            gameObject.destroy();
        }
    }
    private void dropGem(double x, double y) {
        GameObject gem = getGame().createObject("Gem").setPosition(x, y);
        gem.addComponent(new Sprite(Assets.GEM, 18, 18));
        Collider2D area = gem.addComponent(new CircleCollider2D(9).asTrigger());
        area.layer = Layers.PICKUP;
        area.mask = Layers.PLAYER;
        gem.addComponent(new XpGem());
    }
}

