public class XpGem extends Component {
    @Override public void onTrigger(GameObject other) {
        if (!other.hasComponent(PlayerControls.class)) return;
        GameMain game = (GameMain) getGame();
        game.xp++;
        if (game.xp % 10 == 0) {
            game.level++;
            AutoWeapon weapon = other.getComponent(AutoWeapon.class);
            if (weapon != null) { weapon.cooldown = Math.max(0.15, weapon.cooldown * 0.85); weapon.damage += 0.5; }
            getGame().audio.playNote("C6", 0.2, "triangle");
        }
        gameObject.destroy();
    }
}
